"use strict";
$(document).ready(function() {
    // Date and Time Picker
    var dateOfBirthInput = document.getElementById("leads_date_contac");
    if (dateOfBirthInput) {
        flatpickr(dateOfBirthInput, {
            enableTime: true,        // Mengaktifkan pilihan waktu
            dateFormat: "Y-m-d H:i", // Format tanggal dan waktu (contoh: 2023-09-14 15:30)
            time_24hr: true,         // Gunakan format 24 jam
            allowInput: true,        // Izinkan input manual
            defaultHour: 12,         // Jam default
            defaultMinute: 0         // Menit default
        });
    }
});